const app=document.querySelector('#app');
const modes={dictionary:'Słownik',learn:'Fiszki',write:'Pisownia',quiz:'Quiz',test:'Test'};
let mode='dictionary',queue=[],index=0,flipped=false,answered=false,score=0,testQuestions=[],testAnswers=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function start(){if(mode==='test'){startTest();return;}queue=shuffle(WORDS).slice(0,mode==='learn'?WORDS.length:5);index=0;flipped=false;answered=false;score=0;render();}
function nav(){document.body.dataset.mode=mode;document.querySelector('nav').innerHTML=Object.entries(modes).filter(([id])=>id!=='test').map(([id,label])=>`<button data-mode="${id}" ${id===mode?'aria-current="page"':''}>${label}</button>`).join('');}
function render(){nav();if(mode==='test'){renderTest();return;}if(mode==='dictionary'){app.innerHTML=`<div class="heading"><h1>Słownik</h1><span>${WORDS.length} haseł · Business English</span></div><input id="search" type="search" placeholder="Szukaj po polsku lub angielsku" aria-label="Szukaj w słowniku"><div id="words"></div>`;showWords('');return;}
if(index>=queue.length){app.innerHTML=`<section class="exercise"><span class="label">GOTOWE</span><h1>${mode==='learn'?'Koniec fiszek':`Twój wynik: ${score} / ${queue.length}`}</h1><button class="primary" data-action="start">${mode==='learn'?'Wylosuj fiszki':'Nowy zestaw'}</button></section>`;return;}
const w=queue[index];let body='';
if(mode==='learn')body=`<button class="flash" data-action="flip" aria-label="Odwróć fiszkę"><span class="label">${flipped?'POLSKI':'ENGLISH'}</span><strong>${esc(flipped?w.pl:w.en)}</strong><span class="muted">${flipped?esc(w.example):'Kliknij, żeby zobaczyć znaczenie'}</span></button><div class="actions"><button data-action="flip">Odwróć</button><button class="primary" data-action="next">Następna →</button></div>`;
if(mode==='write')body=`<h2>${esc(w.pl)}</h2><p class="muted">Wpisz angielskie hasło.</p><form id="answer"><input name="answer" aria-label="Angielskie hasło" autocomplete="off" spellcheck="false" required><button class="primary" type="submit">Sprawdź</button></form><div id="feedback" role="status"></div>`;
if(mode==='quiz'){const choices=shuffle([w,...shuffle(WORDS.filter(x=>x.id!==w.id)).slice(0,3)]);body=`<h2>${esc(w.pl)}</h2><p class="muted">Wybierz angielskie hasło.</p><div class="choices">${choices.map(x=>`<button data-choice="${x.id}">${esc(x.en)}</button>`).join('')}</div><div id="feedback" role="status"></div>`;}
app.innerHTML=`<div class="heading"><h1>${modes[mode]}</h1><button data-action="start">${mode==='learn'?'Wylosuj fiszki':'Nowy zestaw'}</button></div><section class="exercise"><span class="counter">${index+1} / ${queue.length}</span>${body}</section>`;}
function showWords(query){const list=WORDS.filter(w=>(w.en+' '+w.pl).toLocaleLowerCase('pl').includes(query.toLocaleLowerCase('pl')));document.querySelector('#words').innerHTML=list.length?list.map(w=>`<article class="word"><div><h2>${esc(w.en)}</h2><p>${esc(w.pl)}</p></div><details><summary>Przykład</summary><p>${esc(w.example)}</p><p class="muted">${esc(w.def)}</p></details></article>`).join(''):'<p class="muted">Brak pasujących haseł.</p>';}
function feedback(ok){answered=true;if(ok)score++;document.querySelector('#feedback').innerHTML=`<p class="${ok?'correct':'wrong'}">${ok?'Dobrze!':`Poprawna odpowiedź: <strong>${esc(queue[index].en)}</strong>`}</p><button class="primary" data-action="next">${index+1===queue.length?'Zobacz wynik':'Dalej →'}</button>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='generate'){mode='test';location.hash='test';start();return;}if(b.dataset.mode){mode=b.dataset.mode;location.hash=mode;start();return;}if(b.dataset.action==='start')start();if(b.dataset.action==='flip'){flipped=!flipped;render();}if(b.dataset.action==='next'){index++;flipped=false;answered=false;render();}if(b.dataset.choice&&!answered){const w=queue[index];document.querySelectorAll('[data-choice]').forEach(x=>{x.disabled=true;if(x.dataset.choice===w.id)x.classList.add('correct-choice');else if(x===b)x.classList.add('wrong-choice');});feedback(b.dataset.choice===w.id);}});
document.addEventListener('input',e=>{if(e.target.id==='search')showWords(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id==='test-answer'){e.preventDefault();submitTest(e.target);return;}if(e.target.id!=='answer')return;e.preventDefault();if(answered)return;const field=e.target.elements.answer;const normal=s=>s.trim().toLowerCase().replace(/\s+/g,' ');const w=queue[index];const ok=[w.en,...(w.aliases||[])].some(x=>normal(x)===normal(field.value));field.disabled=true;e.target.querySelector('button').disabled=true;feedback(ok);});
function startTest(){
 testQuestions=shuffle(WORDS).slice(0,10).map((word,i)=>({word,type:'write',choices:shuffle([word,...shuffle(WORDS.filter(x=>x.id!==word.id)).slice(0,3)])}));
 testAnswers=[];index=0;render();
}
function normalAnswer(s){return s.trim().toLowerCase().replace(/\s+/g,' ');}
function renderTest(){
 if(index>=testQuestions.length){
  const points=testAnswers.filter(a=>a.correct).length;
  app.innerHTML=`<section class="exercise"><span class="label">TEST ZAKOŃCZONY</span><h1>Twój wynik: ${points} / ${testQuestions.length}</h1><p class="muted">${Math.round(points/testQuestions.length*100)}% poprawnych odpowiedzi</p><button class="primary" data-action="generate">Wygeneruj nowy test</button></section><h2 class="review-title">Twoje odpowiedzi</h2><div class="test-review">${testQuestions.map((q,i)=>{const a=testAnswers[i];return `<article class="word"><span class="${a.correct?'correct':'wrong'}">${a.correct?'✓ Poprawnie':'✗ Błąd'} · ${i+1}</span><h2>${esc(q.word.pl)}</h2><p>Twoja odpowiedź: ${esc(a.value)}</p>${a.correct?'':`<p class="correct">Poprawna: <strong>${esc(q.word.en)}</strong></p>`}</article>`;}).join('')}</div>`;
  return;
 }
 const q=testQuestions[index];
 app.innerHTML=`<div class="heading"><h1 tabindex="-1">Test pisowni</h1><span>${index+1} / ${testQuestions.length}</span></div><section class="exercise"><p class="muted">10 słówek do wpisania po angielsku · Wynik zobaczysz na końcu.</p><h2 id="test-prompt">${esc(q.word.pl)}</h2><form id="test-answer" class="test-form">${q.type==='choice'?`<fieldset><legend>Wybierz angielskie hasło.</legend><div class="test-options">${q.choices.map(w=>`<label class="test-option"><input type="radio" name="choice" value="${esc(w.id)}" required><span>${esc(w.en)}</span></label>`).join('')}</div></fieldset>`:`<label for="test-input">Wpisz angielskie hasło.</label><input id="test-input" name="written" autocorrect="off" autocapitalize="none" aria-describedby="test-prompt" autocomplete="off" spellcheck="false" required>`}<button type="submit" class="primary">${index+1===testQuestions.length?'Zakończ test':'Dalej →'}</button></form></section>`;
}
function submitTest(form){
 if(mode!=='test'||index>=testQuestions.length||!form.reportValidity())return;
 const q=testQuestions[index];let value,correct;
 if(q.type==='choice'){
  const chosen=q.choices.find(w=>w.id===form.elements.choice.value);if(!chosen)return;
  value=chosen.en;correct=chosen.id===q.word.id;
 }else{
  value=form.elements.written.value.trim();if(!value){form.elements.written.setCustomValidity('Wpisz odpowiedź.');form.elements.written.reportValidity();form.elements.written.setCustomValidity('');return;}
  correct=[q.word.en,...(q.word.aliases||[])].some(w=>normalAnswer(w)===normalAnswer(value));
 }
 testAnswers.push({value,correct});index++;render();document.querySelector('#app h1')?.focus();
}
function route(){const hash=location.hash.slice(1);if(Object.hasOwn(modes,hash)&&mode!==hash){mode=hash;start();}}
window.addEventListener('hashchange',route);if(Object.hasOwn(modes,location.hash.slice(1)))mode=location.hash.slice(1);start();
